files.content:
body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-width: 850px;
  min-height: 100vh;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 1.2em;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
}

div {
  border: 1px solid #000;
  padding: 50px;
  background-color: #fff;
}

h1 {
  margin-top: 0;
}

ol {
  margin: 0;
  padding: 0;
  list-style-position: inside;
  list-style-type: decimal-leading-zero;
}

/* Тут будут стили для маркера */

li::marker {
  color: #23054a;
  font-weight: bold;
  font-size: 2rem;
}

li:not(:last-child) {
  margin-bottom: 10px;
}
